package com.bank.lifecycle.engine;

import com.bank.lifecycle.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

// Simulates the 10-step Spark execution lifecycle in order.
public class SparkLifecycle {
    private static final Logger log = Logger.getLogger(SparkLifecycle.class.getName());

    private boolean sessionStarted;
    private ExecutorService executors; // represents provisioned Executors

    // Step 1: Driver starts the SparkSession.
    public void startSession() {
        log.info("STEP 1: Driver starts SparkSession (master process is up)");
        sessionStarted = true;
    }

    // Step 2: Cluster Manager provisions Executors.
    public void provisionExecutors(int cores) {
        log.info(() -> "STEP 2: Cluster Manager provisions " + cores + " executor cores");
        executors = Executors.newFixedThreadPool(cores);
    }

    // Steps 3-4: build the DAG and 'optimize' it (narrow phase + wide phase).
    public void buildAndOptimizePlan() {
        log.info("STEP 3: DAG built from transformations (filter -> map -> groupBy)");
        log.info("STEP 4: Catalyst optimizes logical->physical (predicate pushdown, pruning)");
    }

    // Steps 5-6: split stages at the shuffle, create one task per partition.
    public List<Integer> planStagesAndTasks(int numPartitions) {
        log.info("STEP 5: DAGScheduler splits into Stage1 (narrow) | Stage2 (post-shuffle)");
        log.info(() -> "STEP 6: TaskScheduler creates " + numPartitions
                + " tasks for Stage1 (one per partition)");
        List<Integer> taskIds = new ArrayList<>();
        for (int i = 0; i < numPartitions; i++) taskIds.add(i);
        return taskIds;
    }

    // Steps 7-8: run stage-1 tasks in parallel, then shuffle into stage-2 buckets.
    public Map<String, BigDecimal> runStagesWithShuffle(List<List<Txn>> partitions) {
        if (!sessionStarted) throw new IllegalStateException("SparkSession not started");
        log.info("STEP 7: Executors run Stage1 tasks (filter SAV2001, map amount) in parallel");

        List<Future<Map<String, BigDecimal>>> futures = new ArrayList<>();
        for (List<Txn> part : partitions) {
            futures.add(executors.submit(() -> {
                Map<String, BigDecimal> local = new HashMap<>();
                for (Txn t : part) {
                    local.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
                }
                return local; // map-side partials
            }));
        }

        log.info("STEP 8: Shuffle exchanges stage1 partials into stage2 buckets by key");
        Map<String, BigDecimal> shuffled = new HashMap<>();
        try {
            for (Future<Map<String, BigDecimal>> f : futures) {
                f.get().forEach((k, v) -> shuffled.merge(k, v, BigDecimal::add));
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("stage execution failed", e);
        }
        return shuffled;
    }

    // Step 9: results returned to Driver (here) or written to storage.
    public void returnResults(Map<String, BigDecimal> results) {
        log.info(() -> "STEP 9: results returned to Driver = " + results);
    }

    // Step 10: stop the session, release executors.
    public void stop() {
        log.info("STEP 10: SparkSession.stop() releases executors and resources");
        if (executors != null) executors.shutdown();
        sessionStarted = false;
    }
}
