package com.bank.lifecycle;

import com.bank.lifecycle.engine.SparkLifecycle;
import com.bank.lifecycle.model.Txn;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.logging.*;

public class LifecycleDemo {
    private static final Logger log = Logger.getLogger(LifecycleDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new LifecycleLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<List<Txn>> partitions = List.of(
            List.of(new Txn("SAV2001", new BigDecimal("1000")),
                    new Txn("CUR3001", new BigDecimal("500"))),
            List.of(new Txn("SAV2001", new BigDecimal("3000")),
                    new Txn("CUR3001", new BigDecimal("700")))
        );

        SparkLifecycle spark = new SparkLifecycle();
        spark.startSession();                    // 1
        spark.provisionExecutors(2);             // 2
        spark.buildAndOptimizePlan();            // 3,4
        spark.planStagesAndTasks(partitions.size()); // 5,6
        Map<String, BigDecimal> result =
            spark.runStagesWithShuffle(partitions);  // 7,8
        spark.returnResults(result);             // 9
        spark.stop();                            // 10

        log.info(() -> "Report complete: total by account = " + result);
    }
}

